{"path": "units/chain/stage3.py", "content": """"Stage 3: aggregate quantities per unit price."""


def total_by_price(rows):
    """Map each ``price`` to the sum of ``qty`` of all rows with that price."""
    totals = {}
    for row in rows:
        price = row["price"]
        totals[price] = totals.get(price, 0) + row["qty"]
    return totals
"}

{"path": "units/chain/stage4.py", "content": """"Stage 4: render the aggregated totals as a report string."""


def report(totals):
    """Return one ``"price:qty\\n"`` line per price, sorted by price ascending."""
    return "".join(
        "{0}:{1}\n".format(price, totals[price]) for price in sorted(totals)
    )
